"use client";

import { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

// Reduced, unhurried 5-word greetings sequence
const GREETINGS = ["Hello", "Namaste", "Bonjour", "Ciao", "Hola"];
const WORD_DURATION = 750; // 750ms per word for a calm, luxury feel

export default function Preloader() {
  const [index, setIndex] = useState(0);
  const [progress, setProgress] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Prevent scrolling while preloader is active
    document.body.style.overflow = "hidden";

    // Unhurried greeting cycle
    const greetingInterval = setInterval(() => {
      setIndex((prev) => {
        if (prev < GREETINGS.length - 1) return prev + 1;
        clearInterval(greetingInterval);
        return prev;
      });
    }, WORD_DURATION);

    // Smooth progress counter over ~3.8 seconds
    const totalTime = GREETINGS.length * WORD_DURATION;
    const intervalTime = totalTime / 100;

    const progressInterval = setInterval(() => {
      setProgress((prev) => {
        if (prev >= 100) {
          clearInterval(progressInterval);
          setTimeout(() => {
            setLoading(false);
            document.body.style.overflow = "auto";
          }, 400);
          return 100;
        }
        return prev + 1;
      });
    }, intervalTime);

    return () => {
      clearInterval(greetingInterval);
      clearInterval(progressInterval);
      document.body.style.overflow = "auto";
    };
  }, []);

  return (
    <AnimatePresence mode="wait">
      {loading && (
        <motion.div
          key="preloader"
          initial={{ y: 0 }}
          exit={{ y: "-100%" }}
          transition={{ duration: 1.2, ease: [0.83, 0, 0.17, 1] }}
          className="fixed inset-0 z-[100] flex flex-col justify-between bg-[#050507] p-8 sm:p-14 text-white select-none shadow-2xl"
        >
          {/* Top Status Bar */}
          <div className="flex items-center justify-between font-mono text-xs text-zinc-500">
            <div className="flex items-center gap-2">
              <span className="h-2 w-2 rounded-full bg-red-500 animate-ping" />
              <span className="text-zinc-300 font-semibold tracking-wider">
                PRATHYUSH.DEV
              </span>
            </div>
            <span className="tracking-widest">SYSTEM_INITIALIZATION</span>
          </div>

          {/* Center Greeting (Instant Text Replacement without Fade) */}
          <div className="flex flex-col items-center justify-center my-auto text-center">
            <div className="h-24 sm:h-32 flex items-center justify-center">
              <div className="flex items-center gap-3 text-5xl sm:text-7xl md:text-8xl font-bold tracking-tight text-white">
                <span className="text-red-500 font-serif italic">✦</span>
                <span>{GREETINGS[index]}</span>
              </div>
            </div>
          </div>


          {/* Bottom Progress Bar & Percentage */}
          <div className="w-full max-w-2xl mx-auto">
            <div className="flex justify-between items-center font-mono text-xs text-zinc-400 mb-2">
              <span>LOADING PORTFOLIO</span>
              <span className="text-red-500 font-bold">{progress}%</span>
            </div>
            <div className="h-1.5 w-full bg-zinc-900 rounded-full overflow-hidden">
              <motion.div
                className="h-full bg-gradient-to-r from-red-600 via-rose-500 to-red-500 transition-all duration-100 ease-out"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}



